import json, math, shutil, struct, subprocess, tempfile, wave, re
from pathlib import Path

INP=Path('data/input_video.mp4')
OUT=Path('compressed_video.mp4')
REPORT=Path('compression_report.json')

if not INP.is_file():
    raise SystemExit(f'missing input: {INP}')
for tool in ('ffmpeg','ffprobe'):
    if shutil.which(tool) is None:
        raise SystemExit(f'missing required tool: {tool}')

def run(cmd):
    return subprocess.run(cmd, check=True, text=True, capture_output=True)

def ffprobe_duration(path: Path) -> float:
    out = run([
        'ffprobe','-v','error','-show_entries','format=duration',
        '-of','default=noprint_wrappers=1:nokey=1', str(path)
    ]).stdout.strip()
    return float(out)

def parse_freeze_segments(stderr: str):
    segs=[]
    cur=None
    for line in stderr.splitlines():
        if 'lavfi.freezedetect.freeze_start' in line:
            m=re.search(r'freeze_start:\s*([0-9.]+)', line)
            if m:
                cur=float(m.group(1))
        elif 'lavfi.freezedetect.freeze_end' in line:
            m=re.search(r'freeze_end:\s*([0-9.]+)', line)
            if m and cur is not None:
                end=float(m.group(1))
                if end>cur:
                    segs.append((cur,end))
                cur=None
    return segs

def detect_opening_end(max_analyze=120.0, min_freeze=2.0):
    # analyze first 2 minutes for frozen frames
    cmd=[
        'ffmpeg','-hide_banner','-t',str(max_analyze),'-i',str(INP),
        '-vf',f'freezedetect=n=0.003:d={min_freeze}', '-an','-f','null','-'
    ]
    proc=subprocess.run(cmd, text=True, capture_output=True)
    # ffmpeg returns 0; but sometimes 0 even if warnings
    segs=parse_freeze_segments(proc.stderr)
    # Consider freeze segments that begin early (opening) and are within first minute
    early=[(s,e) for (s,e) in segs if s < 60.0 and e <= max_analyze]
    if not early:
        return 0.0, []
    end=max(e for _,e in early)
    # If the max end is trivial, treat as no opening
    if end < 5.0:
        return 0.0, early
    # Remove from 0 to end; give a small pad to include any fade-in
    pad=0.2
    return min(max_analyze, end+pad), early

def rms_windows(wav: Path, seconds: float=1.0):
    with wave.open(str(wav),'rb') as f:
        rate=f.getframerate(); width=f.getsampwidth(); ch=f.getnchannels(); frames=f.getnframes()
        raw=f.readframes(frames)
    if width!=2:
        raise RuntimeError('expected 16-bit PCM wav')
    step=max(1,int(rate*seconds)*ch*width)
    values=[]
    for pos in range(0,len(raw),step):
        chunk=raw[pos:pos+step]
        cnt=len(chunk)//2
        if cnt<=0:
            continue
        samples=struct.unpack('<'+'h'*cnt, chunk[:cnt*2])
        values.append(math.sqrt(sum(x*x for x in samples)/cnt))
    return values

def detect_pause_segments(energy, ratio=0.5, minimum=2, window=30):
    if not energy:
        return []
    span=window
    result=[]
    start=None
    for i,value in enumerate(energy):
        lo=max(0,i-span//2); hi=min(len(energy),i+span//2+1)
        avg=sum(energy[lo:hi])/max(1,hi-lo)
        low=(avg>0) and (value < avg*ratio)
        if low and start is None:
            start=i
        if (not low) and start is not None:
            if i-start >= minimum:
                result.append((start,i))
            start=None
    if start is not None and len(energy)-start >= minimum:
        result.append((start,len(energy)))
    return result

def normalize_segments(segments, total):
    clean=[]
    for a,b in sorted(segments):
        a=max(0.0, min(total, float(a)))
        b=max(a,  min(total, float(b)))
        if b-a < 1.0:
            continue
        if clean and a <= clean[-1]['end'] + 1e-6:
            clean[-1]['end']=max(clean[-1]['end'], b)
        else:
            clean.append({'start':a,'end':b})
    for s in clean:
        s['duration']=round(s['end']-s['start'], 3)
    return clean

def build_keep_segments(total, removed):
    keep=[]
    cursor=0.0
    for s in removed:
        if s['start'] > cursor:
            keep.append((cursor, s['start']))
        cursor=max(cursor, s['end'])
    if cursor < total:
        keep.append((cursor,total))
    return keep

def process_video(keep):
