        run(['ffmpeg','-y','-i',str(INP),'-c','copy',str(OUT)])
        return

    parts=[]
    for i,(a,b) in enumerate(keep):
        parts += [
            f"[0:v]trim=start={a}:end={b},setpts=PTS-STARTPTS[v{i}]",
            f"[0:a]atrim=start={a}:end={b},asetpts=PTS-STARTPTS[a{i}]",
        ]
    vs=''.join(f"[v{i}]" for i in range(len(keep)))
    a=''.join(f"[a{i}]" for i in range(len(keep)))
    parts += [
        f"{vs}concat=n={len(keep)}:v=1:a=0[outv]",
        f"{a}concat=n={len(keep)}:v=0:a=1[outa]",
    ]

    run([
        'ffmpeg','-y','-i',str(INP),
        '-filter_complex',';'.join(parts),
        '-map','[outv]','-map','[outa]',
        '-c:v','libx264','-preset','veryfast','-crf','23',
        '-c:a','aac','-b:a','128k',
        str(OUT)
    ])

orig_dur=ffprobe_duration(INP)
opening_end, freeze_segs = detect_opening_end()

removed_pairs=[]
if opening_end >= 5.0:
    removed_pairs.append((0.0, opening_end))

# audio-based pauses after opening
with tempfile.TemporaryDirectory(prefix='silence-') as td:
    wav=Path(td)/'a.wav'
    run(['ffmpeg','-y','-i',str(INP),'-vn','-acodec','pcm_s16le','-ar','16000','-ac','1',str(wav)])
    energy=rms_windows(wav, seconds=1.0)

start_idx=int(math.floor(opening_end))
energy2=energy[start_idx:]
pause_pairs=detect_pause_segments(energy2, ratio=0.5, minimum=2, window=30)
for a,b in pause_pairs:
    removed_pairs.append((a+start_idx, b+start_idx))

removed=normalize_segments(removed_pairs, orig_dur)
keep=build_keep_segments(orig_dur, removed)

# write outputs
process_video(keep)
comp_dur=ffprobe_duration(OUT)

payload={
    'original_duration_seconds': round(orig_dur,3),
    'compressed_duration_seconds': round(comp_dur,3),
    'removed_duration_seconds': round(max(0.0, orig_dur-comp_dur),3),
    'compression_percentage': round((max(0.0, orig_dur-comp_dur)/orig_dur*100) if orig_dur else 0.0, 2),
    'segments_removed': removed,
}
REPORT.write_text(json.dumps(payload, indent=2)+"\n")
print(json.dumps({'opening_end_seconds': round(opening_end,3), 'freeze_segments_first2min': freeze_segs[:10], 'removed_segments': removed}, indent=2))
